use std::collections::BTreeMap;

pub fn patch_config(base: &[(&str, &str)], patches: &[(&str, &str, &str)]) -> Option<Vec<String>> {
    if base.is_empty() {
        return None;
    }

    let mut result = Vec::new();
    let mut base_map: BTreeMap<&str, String> = base.iter().map(|(k, v)| (*k, v.to_string())).collect();

    for (op, key, value) in patches {
        if key.is_empty() {
            return None;
        }

        match op {
            "set" => {
                if base_map.contains_key(key) {
                    base_map.remove(key);
                }
                base_map.insert(key, value.clone());
            }
            "unset" => {
                if base_map.contains_key(key) {
                    base_map.remove(key);
                }
            }
            _ => return None,
        }
    }

    let mut sorted: Vec<String> = base_map.into_iter().collect();
    sorted.sort_by(|a, b| a.cmp(b));

    Some(sorted)
}

